1	package batchreg
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"strconv"
9		"unicode/utf8"
10	)
11	
12	// This file holds the single-record rules shared by the entry points. The
13	// first group serves the two on-disk sources: the registry file (decode,
14	// where stored text is already authoritative) and an import manifest
15	// (ParseManifest, where text is normalized on the way in). Both sources
16	// accept exactly the same four lowercase fields with the same strict JSON
17	// decoding — case-sensitive names, escaped spellings counted, duplicates
18	// visible, strict UTF-8 and strict JSON-integer quantities. The
19	// source-specific differences live in the callers:
20	//
21	//   - text policy: registry records are read verbatim (an empty string is a
22	//     format-level problem handled later by validate), while manifest text is
23	//     trimmed and must stay non-empty;
24	//   - which problem is reported first when one object has several: registry
25	//     records reject any duplicated field before an unknown one, manifest
26	//     records reject whichever anomaly appears first in source order;
27	//   - error types and reason wording, which remain owned by each caller.
28	//
29	// The second group serves the two registration entry points: once a record
30	// has passed validation, Register and Import decide its fate with the single
31	// acceptance rule at the end of this file (new id appended, identical repeat
32	// confirmed, any differing field refused), so the create/duplicate/conflict
33	// decision is maintained in exactly one place.
34	type textPolicy int
35	
36	const (
37		textVerbatim textPolicy = iota // registry record: decode, keep as written
38		textTrimmed                    // manifest record: trim ends, reject blank
39	)
40	
41	// keyEncodingReason is the shared reason sentence for a member NAME that
42	// cannot be decoded (malformed UTF-8 bytes or a lone surrogate escape in the
43	// JSON string source). It is deliberately distinct from the two neighboring
44	// causes: a field VALUE with bad encoding ("must be valid UTF-8 text" /
45	// *EncodingError, naming the field) and a record that is not an object at
46	// all ("record must be a JSON object"). The offending bytes are never
47	// echoed: decoding them would substitute U+FFFD and make distinct names
48	// collide, and the substituted text must never be mistaken for a real name.
49	const keyEncodingReason = "a field name contains bytes that are not valid UTF-8 or holds a lone surrogate escape; the name is rejected instead of being replaced with U+FFFD"
50	
51	// unambiguousBatchID returns the record's batch id only when it can be
52	// determined uniquely and reliably: exactly one "batch" member (counted after
53	// JSON key decoding, so an escaped respelling is the same member) holding one
54	// JSON string whose decoded text is valid UTF-8 and, under textTrimmed,
55	// non-blank after trimming. A missing, duplicated, mistyped, malformed or
56	// blank member yields "" — never a U+FFFD substitution and never one of two
57	// repeated values picked arbitrarily. The trimmed policy returns the
58	// normalized id; the verbatim policy returns the decoded text untouched.
59	func unambiguousBatchID(fields []objectField, policy textPolicy) string {
60		if countField(fields, "batch") != 1 {
61			return ""
62		}
63		raw, ok := findField(fields, "batch")
64		if !ok {
65			return ""
66		}
67		id, err := unmarshalStringStrict(raw)
68		if err != nil {
69			return ""
70		}
71		if policy == textTrimmed {
72			normalized, err := NormalizeField(id)
73			if err != nil {
74				return ""
75			}
76			id = normalized
77		}
78		return id
79	}
80	
81	// memberFault identifies one structural problem with an object's field names.
82	type memberFaultKind int
83	
84	const (
85		faultNone memberFaultKind = iota
86		faultDuplicate
87		faultUnknown
88	)
89	
90	type memberFault struct {
91		field string
92		kind  memberFaultKind
93	}
94	
95	// checkRecordMembers validates the member names of one batch record against
96	// batchRecordFields. With duplicatesFirst it reports the first member name
97	// that repeats anywhere in the object, and only reports an unknown member
98	// when nothing is repeated — the registry file rule. Otherwise it reports
99	// the first anomaly encountered in source order, be it an unknown member or
100	// a repeat — the manifest rule. In source order, an unknown name outranks a
101	// repeat on the same member, matching the original per-member scan. Repeated
102	// keys are detected on the decoded name, so a field hidden behind a JSON
103	// escape is the same member.
104	func checkRecordMembers(fields []objectField, duplicatesFirst bool) memberFault {
105		seen := make(map[string]struct{}, len(fields))
106		var firstDuplicate, firstUnknown memberFault
107		for _, f := range fields {
108			_, known := batchRecordFields[f.key]
109			_, repeated := seen[f.key]
110			seen[f.key] = struct{}{}
111			if !duplicatesFirst {
112				if !known {
113					return memberFault{field: f.key, kind: faultUnknown}
114				}
115				if repeated {
116					return memberFault{field: f.key, kind: faultDuplicate}
117				}
118				continue
119			}
120			if repeated && firstDuplicate.kind == faultNone {
121				firstDuplicate = memberFault{field: f.key, kind: faultDuplicate}
122			}
123			if !known && firstUnknown.kind == faultNone {
124				firstUnknown = memberFault{field: f.key, kind: faultUnknown}
125			}
126		}
127		if duplicatesFirst {
128			if firstDuplicate.kind != faultNone {
129				return firstDuplicate
130			}
131			return firstUnknown
132		}
133		return memberFault{}
134	}
135	
136	// fieldProblem classifies what is wrong with one text member's value,
137	// independently of the error wording each source presents.
138	type fieldProblem int
139	
140	const (
141		fieldOK fieldProblem = iota
142		fieldMissing
143		fieldNotString
144		fieldEncoding
145		fieldBlank
146	)
147	
148	// decodeRecordText reads one text member. found says whether the member
149	// exists; raw is its JSON value. Under textVerbatim every syntactically and
150	// encoding-valid string is returned as written, including "". Under
151	// textTrimmed the value must additionally be non-empty after trimming
152	// (NormalizeField); in that case cause carries NormalizeField's error so the
153	// caller can keep the established reason wording.
154	func decodeRecordText(raw json.RawMessage, found bool, policy textPolicy) (value string, problem fieldProblem, cause error) {
155		if !found {
156			return "", fieldMissing, nil
157		}
158		if trimmed := bytes.TrimSpace(raw); len(trimmed) == 0 || trimmed[0] != '"' {
159			return "", fieldNotString, nil
160		}
161		value, err := unmarshalStringStrict(raw)
162		if errors.Is(err, errStringEncoding) {
163			return "", fieldEncoding, nil
164		}
165		if err != nil {
166			return "", fieldNotString, nil
167		}
168		if policy == textTrimmed {
169			normalized, normErr := NormalizeField(value)
170			if normErr != nil {
171				// After strict decoding the only remaining failure is a blank
172				// result, but keep the cause rather than re-stating its text.
173				return "", fieldBlank, normErr
174			}
175			value = normalized
176		}
177		return value, fieldOK, nil
178	}
179	
180	// quantityShape classifies a JSON quantity token without assigning source-
181	// specific wording. The token is the trimmed raw JSON value; the callers
182	// decide how each class is phrased for registry files versus manifests.
183	type quantityShape int
184	
185	const (
186		qtyValid       quantityShape = iota
187		qtyNotNumeric                // value does not even start as a JSON number digit
188		qtyFractional                // digits followed by '.', 'e' or another non-digit
189		qtyLeadingZero               // "01": no conforming JSON document can reach this
190		qtyOutOfRange                // all digits, but outside signed 64-bit range
191		qtyZero
192	)
193	
194	// classifyJSONQuantity is the shared numeric rule: a strict JSON integer
195	// token (no sign, fraction or exponent) in 1..MaxQuantity. It only inspects
196	// token shape and range — never the surrounding object — so both on-disk
197	// sources and every future caller maintain one quantity definition.
198	func classifyJSONQuantity(token []byte) (int64, quantityShape) {
199		if len(token) == 0 || token[0] < '0' || token[0] > '9' {
200			return 0, qtyNotNumeric
201		}
202		for _, c := range token {
203			if c < '0' || c > '9' {
204				return 0, qtyFractional
205			}
206		}
207		if len(token) > 1 && token[0] == '0' {
208			return 0, qtyLeadingZero
209		}
210		value, err := strconv.ParseInt(string(token), 10, 64)
211		if err != nil {
212			return 0, qtyOutOfRange
213		}
214		if value == 0 {
215			return 0, qtyZero
216		}
217		return value, qtyValid
218	}
219	
220	// recordTextField is one of the three textual members every record carries.
221	type recordTextField struct {
222		name  string
223		value string
224	}
225	
226	// recordTextFields lists batch, product and unit in the fixed order in which
227	// per-field problems are reported, so every validation entry point iterates
228	// the same three members.
229	func recordTextFields(batch, product, unit string) []recordTextField {
230		return []recordTextField{
231			{"batch", batch},
232			{"product", product},
233			{"unit", unit},
234		}
235	}
236	
237	// safeBatchIDForError returns id exactly when it may be cited in an error:
238	// non-empty and valid UTF-8. An empty or malformed id yields "" so no value
239	// and no U+FFFD substitution is ever invented to name a batch.
240	func safeBatchIDForError(id string) string {
241		if id != "" && utf8.ValidString(id) {
242			return id
243		}
244		return ""
245	}
246	
247	// textIssueKind classifies one problem with an already-decoded text field.
248	type textIssueKind int
249	
250	const (
251		textEmpty    textIssueKind = iota // the empty string; whitespace-only text is not empty
252		textEncoding                      // the bytes are not valid UTF-8
253	)
254	
255	// textIssue is one problem with one text field of an already-decoded record.
256	type textIssue struct {
257		field string // "batch", "product" or "unit"
258		kind  textIssueKind
259	}
260	
261	// inspectRecordText examines the three text fields of an already-decoded
262	// record and lists every problem found, in the fixed batch, product, unit
263	// field order with a field's encoding problem listed before its empty-string
264	// problem. Text is checked verbatim — no trimming, no case folding — so
265	// whitespace-only text counts as ordinary non-empty text. This is the single
266	// definition of the text rules for the three entry points that validate
267	// decoded records (Register, Import and Save); each of them picks which issue
268	// to report first according to its own documented ordering.
269	func inspectRecordText(batch, product, unit string) []textIssue {
270		var issues []textIssue
271		for _, tv := range recordTextFields(batch, product, unit) {
272			if !utf8.ValidString(tv.value) {
273				issues = append(issues, textIssue{field: tv.name, kind: textEncoding})
274			}
275			if tv.value == "" {
276				issues = append(issues, textIssue{field: tv.name, kind: textEmpty})
277			}
278		}
279		return issues
280	}
281	
282	// firstTextIssue returns the first issue of the given kind, if any.
283	func firstTextIssue(issues []textIssue, kind textIssueKind) (textIssue, bool) {
284		for _, issue := range issues {
285			if issue.kind == kind {
286				return issue, true
287			}
288		}
289		return textIssue{}, false
290	}
291	
292	// decodedQuantityProblem classifies an already-decoded quantity against the
293	// accepted 1..MaxQuantity window shared by every entry point.
294	type decodedQuantityProblem int
295	
296	const (
297		decodedQtyOK decodedQuantityProblem = iota
298		decodedQtyNotPositive
299		decodedQtyAboveMax
300	)
301	
302	// classifyDecodedQuantity is the single quantity rule for already-decoded
303	// records; the callers decide how each class is phrased.
304	func classifyDecodedQuantity(quantity int64) decodedQuantityProblem {
305		switch {
306		case quantity <= 0:
307			return decodedQtyNotPositive
308		case quantity > MaxQuantity:
309			return decodedQtyAboveMax
310		default:
311			return decodedQtyOK
312		}
313	}
314	
315	// quantityInRange reports whether an already-decoded quantity lies in the
316	// accepted 1..MaxQuantity window shared by every entry point.
317	func quantityInRange(quantity int64) bool {
318		return classifyDecodedQuantity(quantity) == decodedQtyOK
319	}
320	
321	// These wrappers keep the registry-specific reason strings next to the
322	// registry parser while sharing classifyJSONQuantity; the wording predates
323	// the shared classifier and must not change.
324	func registryQuantityError(token []byte) (int64, error) {
325		value, shape := classifyJSONQuantity(token)
326		switch shape {
327		case qtyValid:
328			return value, nil
329		case qtyZero:
330			return 0, errors.New("must be greater than zero")
331		case qtyOutOfRange:
332			return 0, fmt.Errorf("must be an integer no greater than %d", MaxQuantity)
333		case qtyLeadingZero:
334			// No conforming JSON token reaches this branch (leading zeros fail the
335			// document scan); historically such a digit run was parsed on its
336			// numeric value, so keep that exact behavior.
337			parsed, err := strconv.ParseInt(string(token), 10, 64)
338			if err != nil {
339				return 0, fmt.Errorf("must be an integer no greater than %d", MaxQuantity)
340			}
341			if parsed == 0 {
342				return 0, errors.New("must be greater than zero")
343			}
344			return parsed, nil
345		default: // qtyNotNumeric, qtyFractional
346			return 0, fmt.Errorf("must be a JSON integer between 1 and %d", MaxQuantity)
347		}
348	}
349	
350	// manifestQuantityError mirrors the manifest wording: non-numeric values and
351	// signed numbers point at the accepted range, while fractions, exponents and
352	// (defensively) leading zeros each keep their own sentence.
353	func manifestQuantityError(token []byte) (int64, error) {
354		value, shape := classifyJSONQuantity(token)
355		switch shape {
356		case qtyValid:
357			return value, nil
358		case qtyZero:
359			return 0, errors.New(`field "quantity" must be greater than zero`)
360		case qtyLeadingZero:
361			return 0, errors.New(`field "quantity" must be a JSON integer without leading zeros`)
362		case qtyFractional:
363			return 0, errors.New(`field "quantity" must be a JSON integer without sign, fraction or exponent`)
364		case qtyOutOfRange:
365			return 0, fmt.Errorf(`field %q must be an integer no greater than %d`, "quantity", MaxQuantity)
366		default: // qtyNotNumeric
367			return 0, fmt.Errorf(`field %q must be a JSON integer between 1 and %d`, "quantity", MaxQuantity)
368		}
369	}
370	
371	// admission is the single definition of how one already-validated record is
372	// accepted by a set of stored batches — the rule both registration entry
373	// points (Register for a single record, Import for a whole manifest) apply
374	// after their own input validation:
375	//
376	//   - an id the set does not hold is appended after the existing records as
377	//     a new batch;
378	//   - an id the set does hold is confirmed as a duplicate only when product,
379	//     quantity and unit all match the stored record, which is returned
380	//     unchanged — the submitted values never replace it;
381	//   - any differing field refuses the record, with every mismatch listed in
382	//     the fixed product, quantity, unit order.
383	//
384	// Ids compare byte for byte: casing and interior whitespace matter, and the
385	// text is compared exactly as the caller handed it in (the command-line and
386	// manifest entries trim before constructing the Input; direct Go submissions
387	// are kept verbatim). The caller owns everything around the decision —
388	// input validation, the stored-duplicate-id refusal, working on a copy, and
389	// wrapping a refusal in its own error type — so this type never validates
390	// and never reports errors itself.
391	type admission struct {
392		batches   []Batch
393		indexByID map[string]int
394	}
395	
396	// newAdmission starts an acceptance set from stored, which must already be
397	// free of duplicate ids (both callers run storedDuplicateID first). The
398	// slice is taken over, not copied: appended records land in it and the
399	// caller reads the result back from the batches field.
400	func newAdmission(stored []Batch) *admission {
401		a := &admission{batches: stored, indexByID: make(map[string]int, len(stored))}
402		for i, b := range stored {
403			a.indexByID[b.Batch] = i
404		}
405		return a
406	}
407	
408	// acceptance reports how one record fared under the acceptance rule: the
409	// stored or newly created record and whether it was created. When the id is
410	// already held by a conflicting record, only diffs is set — the differing
411	// members among product, quantity and unit, in that order — and the set is
412	// left untouched.
413	type acceptance struct {
414		batch   Batch
415		created bool
416		diffs   []string
417	}
418	
419	// admit applies the acceptance rule to one validated record, appending it
420	// when its id is new.
421	func (a *admission) admit(in Input) acceptance {
422		if idx, known := a.indexByID[in.Batch]; known {
423			existing := a.batches[idx]
424			if diffs := diffFields(existing, in); len(diffs) > 0 {
425				return acceptance{diffs: diffs}
426			}
427			return acceptance{batch: existing}
428		}
429		b := Batch{Batch: in.Batch, Product: in.Product, Quantity: in.Quantity, Unit: in.Unit}
430		a.batches = append(a.batches, b)
431		a.indexByID[in.Batch] = len(a.batches) - 1
432		return acceptance{batch: b, created: true}
433	}
434	
435	// diffFields lists the members of product, quantity and unit in which in
436	// differs from existing, in that fixed order.
437	func diffFields(existing Batch, in Input) []string {
438		var diffs []string
439		if existing.Product != in.Product {
440			diffs = append(diffs, "product")
441		}
442		if existing.Quantity != in.Quantity {
443			diffs = append(diffs, "quantity")
444		}
445		if existing.Unit != in.Unit {
446			diffs = append(diffs, "unit")
447		}
448		return diffs
449	}
