86	// assertSaveFailure checks the contract every rejected mid-save save must
87	// honor towards its caller: a non-nil error that names the actual target path
88	// and carries the injected cause.
89	func assertSaveFailure(t *testing.T, err, cause error, path string) {
90		t.Helper()
