173	// rename proves it by reading the complete new table, including the new
174	// batches, from the file it is asked to move — but the replacement of the
175	// target fails. The existing registry must survive exactly as it was and the
176	// prepared temporary file must be removed, not left behind as a would-be
177	// registry.
178	func TestSaveRenameFailureKeepsExistingRegistryIntact(t *testing.T) {
179		dir, path, original, originalBytes := setupExistingRegistry(t)
180	
181		cause := errors.New("injected rename failure: cannot replace target")
182		renameAttempted := false
183		old := RenameTempFile
184		RenameTempFile = func(oldpath, newpath string) error {
185			renameAttempted = true
186			if newpath != path {
187				t.Errorf("rename must target the actual save path %q, got %q", path, newpath)
188			}
189			prepared, err := os.ReadFile(oldpath)
190			if err != nil {
191				t.Errorf("the prepared content must be readable before the replacement: %v", err)
192				return cause
193			}
194			for _, marker := range []string{"OLD-1", "NEW-1", "NEW-2", "新产品"} {
195				if !bytes.Contains(prepared, []byte(marker)) {
196					t.Errorf("prepared content is missing %q; the save did not get the full new table ready: %s", marker, prepared)
197				}
198			}
199			return cause
200		}
201		t.Cleanup(func() { RenameTempFile = old })
202	
203		submitted := failureSubmission()
204		reg := &Registry{Version: FormatVersion, Batches: append([]Batch(nil), submitted...)}
205		err := Save(path, reg)
206	
207		assertSaveFailure(t, err, cause, path)
208		if !renameAttempted {
209			t.Fatal("the save never reached the replacement step; the failure protection was not exercised")
210		}
211		assertExistingTargetUntouched(t, dir, path, original, originalBytes, reg, submitted)
212	}
213	
214	// The same two mid-save failures against a target that does not exist yet:
215	// the save must end with an error, the target must still not exist, no file
216	// holding part of the submitted batches may appear, and no temporary file may
217	// survive.
218	func TestSaveFailureOnMissingTargetLeavesNoFile(t *testing.T) {
219		injectWriteFailure := func(t *testing.T, cause error) {
220			old := WriteTempContent
221			WriteTempContent = func(f *os.File, data []byte) (int, error) {
222				half := len(data) / 2
223				if _, err := f.Write(data[:half]); err != nil {
224					return 0, err
225				}
226				return half, cause
227			}
228			t.Cleanup(func() { WriteTempContent = old })
229		}
230		injectRenameFailure := func(t *testing.T, cause error) {
231			old := RenameTempFile
232			RenameTempFile = func(oldpath, newpath string) error { return cause }
233			t.Cleanup(func() { RenameTempFile = old })
234		}
235		cases := []struct {
236			name   string
237			inject func(t *testing.T, cause error)
238		}{
239			{"content write incomplete", injectWriteFailure},
240			{"replacement refused", injectRenameFailure},
241		}
242		for _, tc := range cases {
243			t.Run(tc.name, func(t *testing.T) {
244				dir := t.TempDir()
245				path := filepath.Join(dir, "registry.json")
246				cause := errors.New("injected save failure")
