53	// TestMain runs the wrapped single-command mode when requested by the parent
54	// test, and the normal test suite otherwise.
55	func TestMain(m *testing.M) {
56		flag.Parse()
57		if *wrapBatchImport {
58			os.Exit(runWrappedBatchImport())
59		}
60		if *wrapBatchRegister {
61			os.Exit(runWrappedBatchRegister())
62		}
63		os.Exit(m.Run())
64	}
