75	// runWrappedBatchImport performs exactly one batch-import against the files
76	// named in WRAP_REGISTRY/WRAP_INPUT, optionally failing one save step as
77	// selected by WRAP_FAULT. Exit codes mimic the real command: 1 for a reported
78	// batch-import failure (message written to stderr like main does), 3 for a
79	// harness problem inside the child, 0 for success.
80	func runWrappedBatchImport() int {
81		registry := os.Getenv("WRAP_REGISTRY")
82		input := os.Getenv("WRAP_INPUT")
83		reason := os.Getenv("WRAP_REASON")
84		harnessFail := func(format string, args ...any) int {
85			fmt.Fprintf(os.Stderr, "wrap harness: "+format+"\n", args...)
86			return 3
87		}
88		// harnessExit reports a broken test harness from inside an injected hook,
89		// whose signature allows only an error; the parent treats code 3 as a
90		// harness failure rather than a command failure.
91		harnessExit := func(format string, args ...any) error {
92			fmt.Fprintf(os.Stderr, "wrap harness: "+format+"\n", args...)
93			os.Exit(3)
94			return nil
95		}
96		switch saveFault(os.Getenv("WRAP_FAULT")) {
97		case faultWrite:
98			// Part of the new content genuinely reaches the temporary file, then
99			// the write stops with the new table incomplete.
100			batchreg.WriteTempContent = func(f *os.File, data []byte) (int, error) {
101				half := len(data) / 2
102				if _, err := f.Write(data[:half]); err != nil {
103					fmt.Fprintf(os.Stderr, "wrap harness: setup write failed: %v\n", err)
104					os.Exit(3)
105				}
106				return half, errors.New(reason)
107			}
108		case faultRename:
109			// The complete new table must be ready before the replacement is
110			// refused; markers are checked on the prepared temporary file.
111			markers := strings.Split(os.Getenv("WRAP_MARKERS"), ",")
112			batchreg.RenameTempFile = func(oldpath, newpath string) error {
113				if newpath != registry {
114					return harnessExit("rename must target %q, got %q", registry, newpath)
115				}
116				prepared, err := os.ReadFile(oldpath)
117				if err != nil {
118					return harnessExit("prepared temporary file is unreadable: %v", err)
119				}
120				for _, marker := range markers {
121					if !bytes.Contains(prepared, []byte(marker)) {
122						return harnessExit("prepared content is missing %q: %s", marker, prepared)
123					}
124				}
125				return errors.New(reason)
126			}
127		case faultNone:
128		default:
129			return harnessFail("unknown fault %q", os.Getenv("WRAP_FAULT"))
130		}
131		if err := runBatchImport([]string{"--registry", registry, "--input", input}, os.Stdout); err != nil {
132			fmt.Fprintln(os.Stderr, "govflow:", err)
133			return 1
134		}
135		return 0
136	}
