231	// writeManifest serializes the shared rows as one JSON array file.
232	func writeManifest(t *testing.T, path string, rows []manifestRow) []byte {
233		t.Helper()
234		var buf bytes.Buffer
235		buf.WriteByte('[')
236		for i, r := range rows {
237			if i > 0 {
238				buf.WriteByte(',')
239			}
240			data, err := json.Marshal(r)
241			if err != nil {
242				t.Fatal(err)
243			}
244			buf.Write(data)
245		}
246		buf.WriteByte(']')
247		if err := os.WriteFile(path, buf.Bytes(), 0o644); err != nil {
248			t.Fatal(err)
249		}
250		return buf.Bytes()
251	}
