297	// assertNoSaveLeftovers walks dir and fails if a save temporary file
298	// (".govflow-registry-*") or any file other than allowed survived.
299	func assertNoSaveLeftovers(t *testing.T, dir string, allowed ...string) {
300		t.Helper()
301		keep := map[string]bool{}
302		for _, name := range allowed {
303			keep[name] = true
304		}
305		err := filepath.WalkDir(dir, func(path string, d os.DirEntry, err error) error {
306			if err != nil || d.IsDir() {
307				return nil
308			}
309			if strings.HasPrefix(d.Name(), ".govflow-registry-") {
310				t.Errorf("failed import left a temporary registry file behind: %s", path)
311			}
312			if !keep[d.Name()] {
313				t.Errorf("failed import left an unexpected file behind: %s", path)
314			}
315			return nil
316		})
317		if err != nil {
318			t.Fatal(err)
319		}
320	}
