429	// decodeImportEnvelope parses stdout strictly as one JSON object carrying
430	// exactly one member, "results", whose elements are generic objects for
431	// per-key assertions.
432	func decodeImportEnvelope(t *testing.T, raw []byte) []map[string]any {
433		t.Helper()
434		dec := json.NewDecoder(bytes.NewReader(bytes.TrimSpace(raw)))
435		var envelope map[string]json.RawMessage
436		if err := dec.Decode(&envelope); err != nil {
437			t.Fatalf("stdout is not a JSON object: %v (%q)", err, raw)
438		}
439		if err := dec.Decode(&struct{}{}); err != io.EOF {
440			t.Fatalf("stdout must hold exactly one JSON object, got %q", raw)
441		}
442		if len(envelope) != 1 {
443			t.Fatalf("result object must carry exactly \"results\", got keys %v from %q", envelope, raw)
444		}
445		resultsRaw, ok := envelope["results"]
446		if !ok {
447			t.Fatalf("result object is missing \"results\": %q", raw)
448		}
449		var rows []map[string]any
450		if err := json.Unmarshal(resultsRaw, &rows); err != nil {
451			t.Fatalf("results is not an array of objects: %v (%s)", err, resultsRaw)
452		}
453		return rows
454	}
