525	// The success control against an existing registry: with the save healthy the
526	// very manifest that failed above imports. Results arrive in manifest order
527	// with the right statuses and normalized fields, the old records keep their
528	// order and the new batches append in first-occurrence order, and every result
529	// agrees field by field with the final registry.
530	func TestBatchImportCLISaveSuccessAgainstExistingRegistry(t *testing.T) {
531		dir := t.TempDir()
532		registry := filepath.Join(dir, "reg.json")
533		manifest := filepath.Join(dir, "arrivals.json")
534		writeFile(t, registry, importFailureRegistryJSON)
535		if err := os.Chtimes(registry, importFailurePinnedModTime, importFailurePinnedModTime); err != nil {
536			t.Fatal(err)
537		}
538		manifestBytes := writeManifest(t, manifest, importFailureManifestRows)
539	
540		var stdout bytes.Buffer
541		if err := runBatchImport([]string{"--registry", registry, "--input", manifest}, &stdout); err != nil {
542			t.Fatalf("the legal manifest must import when the save does not fail: %v", err)
543		}
544	
545		// A real save must have happened (new batches exist), observable as a new
546		// mtime rather than the pinned one.
547		info, err := os.Stat(registry)
548		if err != nil {
549			t.Fatal(err)
550		}
551		if info.ModTime().Equal(importFailurePinnedModTime) {
552			t.Fatal("a creating import must replace the file; the pinned mtime survived")
553		}
554	
555		assertImportResults(t, stdout.Bytes(), manifestResultsAgainstExisting)
556		stored := readStoredBatches(t, registry)
557		assertStoredBatches(t, registry, storedBatchesAfterExisting)
558		assertResultsMatchRegistry(t, manifestResultsAgainstExisting, stored)
559		assertFileUnchanged(t, manifest, manifestBytes)
560		assertNoSaveLeftovers(t, dir, filepath.Base(manifest), filepath.Base(registry))
561	}
