581	// The batch id stays out of the error when it cannot be determined uniquely
582	// and reliably: missing, mistyped, blank, malformed or duplicated "batch"
583	// members — duplicates even with identical values or an escaped respelling.
584	func TestParseManifestRecordErrorOmitsAmbiguousBatch(t *testing.T) {
585		cases := map[string]string{
586			"missing batch":             `[{"product":"P","quantity":1,"unit":"kg","supplier":"S"}]`,
587			"numeric batch":             `[{"batch":7,"product":"P","quantity":1,"unit":"kg","supplier":"S"}]`,
