1	package batchreg
2	
3	import (
4		"bytes"
5		"errors"
6		"fmt"
7		"os"
8		"path/filepath"
9		"strconv"
10		"strings"
11		"testing"
12	)
13	
14	// This file is the regression net for Save when the caller supplies the whole
15	// registry table directly, rather than building it through Register or
16	// Import. The rule under guard: a save that succeeds must read back through
17	// Load exactly as supplied, while a rejected save behaves as if it never ran —
18	// the target file's bytes and modification time stay untouched (or the file is
19	// never created), no temporary file remains, and the caller's records and
20	// their order are unchanged.
21	func saveBatch(batch, product string, quantity int64, unit string) Batch {
22		return Batch{Batch: batch, Product: product, Quantity: quantity, Unit: unit}
23	}
24	
25	func assertBatchesEqual(t *testing.T, got, want []Batch) {
26		t.Helper()
27		if len(got) != len(want) {
28			t.Fatalf("got %d records, want %d: %+v", len(got), len(want), got)
29		}
30		for i := range want {
31			if got[i] != want[i] {
32				t.Errorf("record %d = %+v, want %+v", i+1, got[i], want[i])
33			}
34		}
35	}
36	
37	// assertNoLeftoverTempFiles walks root and fails if any save temp file
38	// (".govflow-registry-*.tmp") survived a rejected save.
39	func assertNoLeftoverTempFiles(t *testing.T, root string) {
40		t.Helper()
41		err := filepath.WalkDir(root, func(path string, d os.DirEntry, err error) error {
42			if err != nil || d.IsDir() {
43				return nil
44			}
45			if strings.HasPrefix(d.Name(), ".govflow-registry-") {
46				t.Errorf("rejected save left a temporary file behind: %s", path)
47			}
48			return nil
49		})
50		if err != nil {
51			t.Fatal(err)
52		}
53	}
54	
55	// With no batches, "batches" is written as an empty array, never null, whether
56	// the caller left the slice uninitialized or emptied it, and the file reads
57	// back as a usable empty version-1 registry.
58	func TestSaveEmptyRegistryWritesEmptyArrayAndReadsBack(t *testing.T) {
59		cases := []struct {
60			name    string
61			batches []Batch
62			wantNil bool
63		}{
64			{"uninitialized slice", nil, true},
65			{"already empty slice", []Batch{}, false},
66		}
67		for _, tc := range cases {
68			t.Run(tc.name, func(t *testing.T) {
69				path := filepath.Join(t.TempDir(), "registry.json")
70				reg := &Registry{Version: FormatVersion, Batches: tc.batches}
71				if err := Save(path, reg); err != nil {
72					t.Fatal(err)
73				}
74				data, err := os.ReadFile(path)
75				if err != nil {
76					t.Fatal(err)
77				}
78				if !bytes.Contains(data, []byte(`"batches": []`)) {
79					t.Fatalf("empty registry must serialize batches as [], got %s", data)
80				}
81				if bytes.Contains(data, []byte("null")) {
82					t.Fatalf("empty registry must not contain null: %s", data)
83				}
84				got, existed, err := Load(path)
85				if err != nil || !existed {
86					t.Fatalf("empty registry must read back: existed=%v err=%v", existed, err)
87				}
88				if got.Version != FormatVersion || len(got.Batches) != 0 {
89					t.Fatalf("read-back registry = %+v", got)
90				}
91				// Encoding takes a shallow copy, so the caller's slice header
92				// (nil included) must be left exactly as it was passed in.
93				if (reg.Batches == nil) != tc.wantNil {
94					t.Fatalf("Save mutated the Batches header: nil=%v, want nil=%v", reg.Batches == nil, tc.wantNil)
95				}
96			})
97		}
98	}
99	
100	// On success the records read back in submission order with all four fields
101	// intact: quantity bounds, legal Chinese, a genuine U+FFFD the caller typed,
102	// and whitespace of every kind kept verbatim.
103	func TestSaveRoundTripPreservesOrderAndFields(t *testing.T) {
104		fffd := string(rune(0xFFFD))
105		want := []Batch{
106			// Leading/trailing whitespace and legal Chinese stay verbatim;
107			// quantity at the inclusive lower bound.
108			saveBatch(" B-1 ", " 产品 A ", 1, " 千克 "),
109			// Interior whitespace is part of each text value.
110			saveBatch("B 2", "P  7", 7, "b o x"),
111			// Whitespace-only non-empty text; quantity at the inclusive upper bound.
112			saveBatch(" ", "\t", MaxQuantity, "\n"),
113			// A replacement character the caller genuinely entered is ordinary text.
114			saveBatch("批次-"+fffd, "P"+fffd+"Q", 42, fffd),
115		}
116		path := filepath.Join(t.TempDir(), "registry.json")
117		reg := &Registry{Version: FormatVersion, Batches: append([]Batch(nil), want...)}
118		if err := Save(path, reg); err != nil {
119			t.Fatal(err)
120		}
121		data, err := os.ReadFile(path)
122		if err != nil {
123			t.Fatal(err)
124		}
125		// The genuine U+FFFD is written as its real UTF-8 bytes, never stripped
126		// or re-encoded as an escape.
127		if !bytes.Contains(data, []byte{0xEF, 0xBF, 0xBD}) {
128			t.Fatalf("saved file lost the genuine U+FFFD: %s", data)
129		}
130	
131		got, existed, err := Load(path)
132		if err != nil || !existed {
133			t.Fatalf("saved registry must read back: existed=%v err=%v", existed, err)
134		}
135		if got.Version != FormatVersion {
136			t.Fatalf("read-back version = %d, want %d", got.Version, FormatVersion)
137		}
138		assertBatchesEqual(t, got.Batches, want)
139		// The caller's own records survive the save unchanged and in order.
140		assertBatchesEqual(t, reg.Batches, want)
141	}
142	
143	// Every invalid record rejects the whole save, and the error names the target
144	// file, the 1-based record position, the field and the reason. The batch id is
145	// cited verbatim only when the batch field itself is non-empty valid UTF-8; an
146	// empty or malformed id is never cited, and never replaced with U+FFFD to
147	// identify the record.
148	func TestSaveRejectsInvalidRecords(t *testing.T) {
149		fffd := string(rune(0xFFFD))
150		good := func() []Batch {
151			return []Batch{
152				saveBatch("B1", "P1", 1, "kg"),
153				saveBatch("B2", "P2", 2, "box"),
154				saveBatch("B3", "P3", 3, "m"),
155			}
156		}
157		cases := []struct {
158			name   string
159			mutate func([]Batch)
160			pos    int
161			field  string
162			batch  string // "" when the error must carry no batch id
163			reason string
164		}{
165			{"empty batch on first record", func(b []Batch) { b[0].Batch = "" }, 1, "batch", "", "must not be empty"},
166			{"empty product", func(b []Batch) { b[0].Product = "" }, 1, "product", "B1", "must not be empty"},
167			{"empty unit on second record", func(b []Batch) { b[1].Unit = "" }, 2, "unit", "B2", "must not be empty"},
168			{"zero quantity on second record", func(b []Batch) { b[1].Quantity = 0 }, 2, "quantity", "B2", "between 1 and"},
169			{"negative quantity on third record", func(b []Batch) { b[2].Quantity = -5 }, 3, "quantity", "B3", "between 1 and"},
170			{"malformed utf8 batch", func(b []Batch) { b[0].Batch = string([]byte{'B', 0xFF}) }, 1, "batch", "", "valid UTF-8"},
171			{"malformed utf8 product names valid batch", func(b []Batch) { b[2].Product = string([]byte{'P', 0xFF}) }, 3, "product", "B3", "valid UTF-8"},
172			{"malformed utf8 unit", func(b []Batch) { b[1].Unit = string([]byte{'k', 'g', 0xFF}) }, 2, "unit", "B2", "valid UTF-8"},
173		}
174		for _, tc := range cases {
175			t.Run(tc.name, func(t *testing.T) {
176				dir := t.TempDir()
177				path := filepath.Join(dir, "registry.json")
178				batches := good()
179				tc.mutate(batches)
180				submitted := append([]Batch(nil), batches...)
181				reg := &Registry{Version: FormatVersion, Batches: batches}
182	
183				err := Save(path, reg)
184				if err == nil {
185					t.Fatal("Save must reject the invalid table")
186				}
187				var fe *FormatError
188				if !errors.As(err, &fe) {
189					t.Fatalf("want *FormatError, got %v", err)
190				}
191				if fe.Position != tc.pos || fe.Field != tc.field || fe.Batch != tc.batch {
192					t.Fatalf("FormatError = position %d field %q batch %q, want position %d field %q batch %q",
193						fe.Position, fe.Field, fe.Batch, tc.pos, tc.field, tc.batch)
194				}
195				msg := err.Error()
196				for _, want := range []string{
197					path,
198					fmt.Sprintf("batches record %d", tc.pos),
199					strconv.Quote(tc.field),
200					tc.reason,
201				} {
202					if !strings.Contains(msg, want) {
203						t.Errorf("error %q must mention %q", msg, want)
204					}
205				}
206				if tc.batch == "" {
207					if strings.Contains(msg, "(batch \"") {
208						t.Errorf("error must not invent a batch id: %q", msg)
209					}
210				} else if !strings.Contains(msg, "(batch "+strconv.Quote(tc.batch)+")") {
211					t.Errorf("error must cite batch %q verbatim: %q", tc.batch, msg)
212				}
213				if strings.Contains(msg, fffd) {
214					t.Errorf("error must not identify a record via a substituted U+FFFD: %q", msg)
215				}
216	
217				// Rejection happens before any file system change.
218				if _, err := os.Stat(path); !os.IsNotExist(err) {
219					t.Fatalf("rejected save must not create the target file, stat err=%v", err)
220				}
221				assertNoLeftoverTempFiles(t, dir)
222				assertBatchesEqual(t, reg.Batches, submitted)
223			})
224		}
225	}
