227	// When earlier records are legal and a later one invalidates the table, no
228	// part of the earlier records may land: validation finishes (and fails)
229	// before any directory is created or any byte is written.
230	func TestSaveRejectsLateInvalidRecordWithoutPartialWrite(t *testing.T) {
231		cases := []struct {
232			name    string
233			batches []Batch
234			pos     int
235			field   string
236			batch   string
237			reason  string
238		}{
239			{
240				"empty unit on record 3",
