301	// Two records sharing one byte-for-byte identical batch id reject the whole
302	// save even when product, quantity and unit are identical too. Save persists
303	// a complete table; it never applies Register/Import's duplicate-confirmation
304	// rule. The error names the id and both 1-based positions.
305	func TestSaveRejectsDuplicateBatchIDs(t *testing.T) {
306		cases := []struct {
307			name    string
308			batches []Batch
309			first   int
310			second  int
311			batch   string
312		}{
313			{
314				"identical records",
315				[]Batch{
316					saveBatch("DUP", "P", 5, "kg"),
317					saveBatch("DUP", "P", 5, "kg"),
318				},
319				1, 2, "DUP",
320			},
321			{
322				"first and third records",
323				[]Batch{
324					saveBatch("DUP", "P", 5, "kg"),
325					saveBatch("OTHER", "Q", 6, "g"),
326					saveBatch("DUP", "P", 5, "kg"),
327				},
328				1, 3, "DUP",
329			},
330			{
331				"identical whitespace-bearing id",
332				[]Batch{
333					saveBatch(" DUP ", "P", 5, "kg"),
334					saveBatch(" DUP ", "P", 5, "kg"),
335				},
336				1, 2, " DUP ",
337			},
338		}
339		for _, tc := range cases {
340			t.Run(tc.name, func(t *testing.T) {
341				dir := t.TempDir()
342				path := filepath.Join(dir, "registry.json")
343				submitted := append([]Batch(nil), tc.batches...)
344				reg := &Registry{Version: FormatVersion, Batches: tc.batches}
345	
346				err := Save(path, reg)
347				if err == nil {
348					t.Fatal("Save must reject duplicate batch ids")
349				}
350				var dup *DuplicateIDError
351				if !errors.As(err, &dup) {
352					t.Fatalf("want *DuplicateIDError, got %v", err)
353				}
354				if dup.Batch != tc.batch || dup.First != tc.first || dup.Second != tc.second {
355					t.Fatalf("DuplicateIDError = batch %q records %d,%d, want %q records %d,%d",
356						dup.Batch, dup.First, dup.Second, tc.batch, tc.first, tc.second)
357				}
358				msg := err.Error()
359				for _, want := range []string{
360					path,
361					strconv.Quote(tc.batch),
362					fmt.Sprintf("records %d and %d", tc.first, tc.second),
363				} {
364					if !strings.Contains(msg, want) {
365						t.Errorf("error %q must mention %q", msg, want)
366					}
367				}
368	
369				if _, err := os.Stat(path); !os.IsNotExist(err) {
370					t.Fatalf("rejected save must not create the target file, stat err=%v", err)
371				}
372				assertNoLeftoverTempFiles(t, dir)
373				assertBatchesEqual(t, reg.Batches, submitted)
374			})
375		}
376	}
