378	// Ids are compared by their original text: casing and leading or trailing
379	// whitespace distinguish batches, and tables using only such distinct ids
380	// save and read back normally.
381	func TestSaveDistinguishesBatchIDsVerbatim(t *testing.T) {
382		want := []Batch{
383			saveBatch("B-1", "P", 1, "kg"),
384			saveBatch("b-1", "P", 2, "kg"), // different case
385			saveBatch("B-1 ", "P", 3, "kg"),
386			saveBatch(" B-1", "P", 4, "kg"),
387		}
388		path := filepath.Join(t.TempDir(), "registry.json")
389		reg := &Registry{Version: FormatVersion, Batches: append([]Batch(nil), want...)}
390		if err := Save(path, reg); err != nil {
391			t.Fatalf("ids differing only by case or edge whitespace are distinct: %v", err)
392		}
393		got, existed, err := Load(path)
394		if err != nil || !existed {
395			t.Fatalf("saved registry must read back: existed=%v err=%v", existed, err)
396		}
397		assertBatchesEqual(t, got.Batches, want)
398	}
399	
400	// When the target already exists, any rejected save (invalid record, bad
401	// encoding or duplicate id) leaves its bytes and modification time exactly as
402	// they were; the old registry still loads with its original record.
403	func TestSaveRejectionKeepsExistingFileUnchanged(t *testing.T) {
404		const oldContent = `{"version":1,"batches":[{"batch":"OLD","product":"P","quantity":5,"unit":"kg"}]}`
405		bad := string([]byte{0xFF})
406		cases := map[string][]Batch{
407			"invalid later record": {
408				saveBatch("NEW1", "P", 1, "kg"),
409				saveBatch("NEW2", "", 2, "kg"),
410			},
411			"duplicate identical records": {
412				saveBatch("DUP", "P", 1, "kg"),
413				saveBatch("DUP", "P", 1, "kg"),
414			},
415			"malformed utf8": {
416				saveBatch("NEW1", "P", 1, "kg"),
417				saveBatch("N"+bad, "P", 2, "kg"),
418			},
419		}
420		for name, batches := range cases {
421			t.Run(name, func(t *testing.T) {
422				dir := t.TempDir()
423				path := filepath.Join(dir, "registry.json")
424				writeRegistry(t, path, oldContent)
425	
426				before, err := os.Stat(path)
427				if err != nil {
428					t.Fatal(err)
429				}
430				beforeBytes, err := os.ReadFile(path)
431				if err != nil {
432					t.Fatal(err)
433				}
434	
435				reg := &Registry{Version: FormatVersion, Batches: batches}
436				if err := Save(path, reg); err == nil {
437					t.Fatal("Save must reject the table")
438				}
439	
440				after, err := os.Stat(path)
441				if err != nil {
442					t.Fatal(err)
443				}
444				if after.ModTime() != before.ModTime() || after.Size() != before.Size() {
445					t.Fatalf("rejected save touched the file: before %+v, after %+v", before, after)
446				}
447				afterBytes, err := os.ReadFile(path)
448				if err != nil {
449					t.Fatal(err)
450				}
451				if string(afterBytes) != string(beforeBytes) {
452					t.Fatalf("rejected save changed the file bytes:\nbefore %s\nafter  %s", beforeBytes, afterBytes)
453				}
454				loaded, existed, err := Load(path)
455				if err != nil || !existed || len(loaded.Batches) != 1 || loaded.Batches[0].Batch != "OLD" {
456					t.Fatalf("old registry not preserved: %+v existed=%v err=%v", loaded, existed, err)
457				}
458				assertNoLeftoverTempFiles(t, dir)
459			})
460		}
461	}
462	
463	// Neither success nor failure may alter the records the caller supplied,
464	// including their order; the failure tables keep records around and after the
465	// offending one exactly as passed.
466	func TestSaveDoesNotMutateCallerRegistry(t *testing.T) {
467		fffd := string(rune(0xFFFD))
468		records := []Batch{
469			saveBatch(" B ", "P 1", 9, "kg"),
470			saveBatch("批次", "产品", MaxQuantity, "单位"),
471			saveBatch("x"+fffd, "y", 1, "z"),
472		}
473	
474		t.Run("successful save", func(t *testing.T) {
475			path := filepath.Join(t.TempDir(), "registry.json")
476			snapshot := append([]Batch(nil), records...)
477			reg := &Registry{Version: FormatVersion, Batches: append([]Batch(nil), records...)}
478			if err := Save(path, reg); err != nil {
479				t.Fatal(err)
480			}
481			assertBatchesEqual(t, reg.Batches, snapshot)
482			if reg.Version != FormatVersion {
483				t.Fatalf("Version = %d", reg.Version)
484			}
485		})
486	
487		failures := map[string][]Batch{
488			"duplicate id in the middle": {
489				records[0], records[1], records[1], records[2],
490			},
491			"invalid record after valid prefix": {
492				records[0],
493				saveBatch("B2", "P", 0, "kg"),
494				records[2],
495			},
496		}
497		for name, batches := range failures {
498			t.Run(name, func(t *testing.T) {
499				path := filepath.Join(t.TempDir(), "registry.json")
500				snapshot := append([]Batch(nil), batches...)
501				reg := &Registry{Version: FormatVersion, Batches: batches}
502				if err := Save(path, reg); err == nil {
503					t.Fatal("Save must reject the table")
504				}
505				assertBatchesEqual(t, reg.Batches, snapshot)
506			})
507		}
508	}
